     /// otherwise a no-op (boot tables already cover it). Either way the page ends up `accessible`.
     pub open spec fn spec_map_page(self, page: int) -> IdentityMapView {
         if self.initialized {
             self.spec_install_page(page)
         } else {
             self
         }
     }
