232. ///
233. /// # Errors
234. ///
235. /// - [`ErrorCode::BadAddress`]: The target range is invalid or overflows.
236. /// - Any error propagated by the lazy identity mapper while preparing the range.
237. ///
238. /// # Notes
239. ///
240. /// If `size == 0`, this function is a no-op and returns success.
241. ///
242. pub(crate) fn memset(base: *mut u8, value: u8, size: usize) -> Result<(), Error> {
243.     // Check if fill size is zero.
244.     if size == 0 {
